<?php
require_once __DIR__ . '/../includes/functions.php';
if (current_user()) redirect(current_user()['role'] . '/dashboard.php');
$errors = [];
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    post_guard();
    $name = trim($_POST['name'] ?? ''); $email = trim($_POST['email'] ?? ''); $phone = trim($_POST['phone'] ?? ''); $password = $_POST['password'] ?? ''; $confirm = $_POST['confirm_password'] ?? ''; $role = $_POST['role'] ?? 'customer';
    if ($name === '' || !filter_var($email, FILTER_VALIDATE_EMAIL) || $phone === '') $errors[] = 'Please complete your name, email, and mobile number.';
    if (strlen($password) < 8 || $password !== $confirm) $errors[] = 'Passwords must match and contain at least 8 characters.';
    if (!in_array($role, ['customer', 'vendor'], true)) $role = 'customer';
    foreach (['name'=>120,'email'=>160,'phone'=>30,'salon_name'=>160,'address'=>255,'city'=>100] as $key=>$limit) {
        if (mb_strlen($_POST[$key]??'')>$limit) $errors[]='Please shorten your '.str_replace('_',' ',$key).'.';
    }
    if (strlen($password)>72) $errors[]='Password must be at most 72 bytes.';
    if (!$errors) { $exists = db()->prepare('SELECT id FROM users WHERE email = ?'); $exists->execute([$email]); if ($exists->fetch()) $errors[] = 'An account with that email already exists.'; }
    if (!$errors) {
        $pdo = db(); $pdo->beginTransaction();
        try {
            $status = $role === 'vendor' ? 'pending' : 'active'; $stmt = $pdo->prepare('INSERT INTO users (name,email,phone,password_hash,role,status) VALUES (?,?,?,?,?,?)'); $stmt->execute([$name,$email,$phone,password_hash($password,PASSWORD_DEFAULT),$role,$status]); $userId = (int)$pdo->lastInsertId();
            if ($role === 'vendor') { $salonName = trim($_POST['salon_name'] ?? '') ?: $name . ' Studio'; $slug = strtolower(trim(preg_replace('/[^a-z0-9]+/i', '-', $salonName), '-')) . '-' . $userId; $salon = $pdo->prepare("INSERT INTO salons (vendor_id,name,slug,description,address,city,phone,status) VALUES (?,?,?,?,?,?,?,'pending')"); $salon->execute([$userId,$salonName,$slug,'A new partner salon on The Barber Company.',trim($_POST['address'] ?? '') ?: 'Address to be updated',trim($_POST['city'] ?? '') ?: 'Mumbai',$phone]); $pdo->commit(); flash('success', 'Your partner application is submitted. We will review it shortly.'); redirect('auth/login.php'); }
            $pdo->commit(); login_user(['id'=>$userId,'role'=>'customer']); redirect('customer/dashboard.php');
        } catch (Throwable $exception) { $pdo->rollBack(); $errors[] = report_error($exception); }
    }
}
$page_title = 'Create your account'; include __DIR__ . '/../includes/header.php';
?><main class="auth-wrap"><div class="auth-card" style="max-width:620px"><div class="section-label">Join the club</div><h1 class="display-6 mb-2">Make your next appointment count.</h1><p class="muted mb-4">Create a customer account, or apply to bring your salon to the directory.</p><?php foreach ($errors as $error): ?><div class="alert alert-danger py-2 small"><?= e($error) ?></div><?php endforeach; ?><form method="post" class="row g-3"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="col-12"><label for="roleSelect" class="form-label small fw-semibold">I am joining as</label><select class="form-select" name="role" id="roleSelect"><option value="customer">A customer</option><option value="vendor" <?= ($_POST['role'] ?? '') === 'vendor' ? 'selected' : '' ?>>A salon partner</option></select></div><div class="col-md-6"><label for="name" class="form-label small fw-semibold">Full name</label><input class="form-control" id="name" name="name" value="<?= old('name') ?>"></div><div class="col-md-6"><label for="phone" class="form-label small fw-semibold">Mobile number</label><input class="form-control" id="phone" name="phone" value="<?= old('phone') ?>"></div><div class="col-12"><label for="email" class="form-label small fw-semibold">Email</label><input class="form-control" type="email" id="email" name="email" value="<?= old('email') ?>"></div><div id="vendorFields" class="row g-3" style="display:none"><div class="col-md-6"><label for="salon_name" class="form-label small fw-semibold">Salon name</label><input class="form-control" id="salon_name" name="salon_name" value="<?= old('salon_name') ?>"></div><div class="col-md-6"><label for="city" class="form-label small fw-semibold">City</label><input class="form-control" id="city" name="city" value="<?= old('city') ?>"></div><div class="col-12"><label for="address" class="form-label small fw-semibold">Salon address</label><input class="form-control" id="address" name="address" value="<?= old('address') ?>"></div></div><div class="col-md-6"><label for="password" class="form-label small fw-semibold">Password</label><input class="form-control" type="password" id="password" name="password"></div><div class="col-md-6"><label for="confirm_password" class="form-label small fw-semibold">Confirm password</label><input class="form-control" type="password" id="confirm_password" name="confirm_password"></div><div class="col-12"><button class="btn btn-brand w-100">Create account <i class="bi bi-arrow-right ms-2"></i></button></div></form><p class="text-center small muted mt-4 mb-0">Already a member? <a class="text-decoration-underline" href="<?= e(url('auth/login.php')) ?>">Sign in</a></p></div></main><script>const roleSelect=document.getElementById('roleSelect');const vendorFields=document.getElementById('vendorFields');function toggleVendor(){vendorFields.style.display=roleSelect.value==='vendor'?'flex':'none'}roleSelect.addEventListener('change',toggleVendor);toggleVendor();</script><?php include __DIR__ . '/../includes/footer.php'; ?>
